<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='reports';$pageTitle='Recruiter Reports';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$uid=(int)($user['id']??$user['user_id']??0);$stats=['shortlists'=>0,'candidates'=>0];if(rc_has_table($conn,'recruiter_shortlists')){$s=$conn->prepare("SELECT COUNT(DISTINCT rs.id) shortlists,COUNT(DISTINCT rsc.candidate_id) candidates FROM recruiter_shortlists rs LEFT JOIN recruiter_shortlist_candidates rsc ON rsc.shortlist_id=rs.id WHERE rs.recruiter_id=?");$s->bind_param('i',$uid);$s->execute();$stats=array_merge($stats,$s->get_result()->fetch_assoc()?:[]);$s->close();}require __DIR__.'/_layout_start.php';?><div class="rc-page-header"><span class="rc-eyebrow">Recruitment Insights</span><h2>Reports</h2><p>Review shortlist output and recruiter activity.</p></div><section class="rc-stats rc-stats--2"><article><i class="fas fa-list-check"></i><strong><?=number_format((int)$stats['shortlists'])?></strong><span>Shortlists</span></article><article><i class="fas fa-users"></i><strong><?=number_format((int)$stats['candidates'])?></strong><span>Unique Shortlisted</span></article></section><div class="rc-card"><div class="rc-empty"><i class="fas fa-chart-column"></i><strong>Reporting foundation ready</strong><span>Extend this page with client response, placement and conversion metrics once those workflow tables are confirmed.</span></div></div><?php require __DIR__.'/_layout_end.php';?>